import numpy as np

def false_alarm_rate(n, m, sims, seed):
    rng = np.random.default_rng(seed)
    alarms = 0
    for _ in range(sims):
        e = rng.standard_normal(n)
        if ljung_box_q(e, m)[1] < 0.05:
            alarms += 1
    return round(alarms / sims, 2)

from statsmodels.stats.diagnostic import acorr_ljungbox

def is_white_noise(x, m=10, alpha=0.05):
    out = acorr_ljungbox(x, lags=[m])
    p = float(out['lb_pvalue'].iloc[0])
    return bool(p >= alpha)
